38	        let choices = wizard_choices(packages.iter().copied(), changed);
39	        let mut prompter = TerminalAddPrompter { _allowed: prompts };
40	        let Some((chosen, written)) = run_wizard(&choices, summary.clone(), &mut prompter)? else {
41	            return Ok(ExitCode::SUCCESS);
42	        };
43	        entries = chosen;
44	        summary = Some(written);
45	        wizard = true;
46	    } else {
47	        // Non-interactive mode (flags supplied via CLI or agent)
48	        for pkg_str in args.packages {
49	            let (name, sev_str) = pkg_str
50	                .rsplit_once(':')
51	                .ok_or_else(|| CliError::AddInvalidPackageSpec { spec: pkg_str.clone() })?;
52	
53	            let severity = parse_severity(sev_str)?;
54	
55	            // Resolves by any registered native name (not just a package's
56	            // primary/display name), reporting E102/E103 on a miss or
57	            // ecosystem-ambiguous bare name.
58	            callisto_graph::ConfigError::require_qualified(name, "--package")
59	                .map_err(callisto_graph::GraphError::Config)?;
60	            let resolved = ws.identity.resolve(name)?;
61	
62	            let package = resolved.display_name();
63	            if entries.iter().any(|e: &Entry| e.name == package) {
64	                return Err(CliError::AddDuplicatePackage {
65	                    package: name.to_owned(),
66	                });
67	            }
68	
69	            entries.push(Entry {
70	                // Use display_name() so "cargo/foo" is preserved, not just "foo".
71	                // In a polyglot workspace, the bare name is ambiguous across ecosystems.
72	                name: package,
73	                severity,
74	            });
75	        }
76	    }
77	
78	    let summary = summary.ok_or(CliError::AddSummaryRequired)?;
79	    let changeset = Changeset {
80	        entries,
81	        summary: summary.0,
82	    };
83	    let text = callisto_model::format::write_changeset(&changeset)?;
84	
85	    let changeset_dir = ws.root.join(&ws.config.changesets_dir);
86	    let archive_dir = ws.root.join(ws.config.pre_archive_dir());
87	
88	    let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) else {
89	        // Compute what WOULD be written, but never touch disk.
90	        let filename = unused_changeset_filename(&changeset_dir, &archive_dir)?;
91	        let rel_path = ws.config.changesets_dir.join(&filename).to_string_lossy().into_owned();
92	        match global.format {
93	            OutputFormat::Json => {
94	                let report = AddReport {
95	                    schema_version: SCHEMA_VERSION,
96	                    path: rel_path,
97	                    content: Some(text),
98	                    diagnostics: vec![],
99	                };
100	                emit_report(&mut std::io::stdout(), &report, true)?;
101	            }
102	            OutputFormat::Text => {
103	                emit_line(&format!(
104	                    "[DRY-RUN] Would add changeset: {rel_path} (no files written)\n\n{text}"
105	                ))?;
106	            }
107	        }
108	        return Ok(ExitCode::SUCCESS);
109	    };
110	
111	    fs::create_dir_all(&changeset_dir)?;
112	    let filename = create_changeset(&changeset_dir, &archive_dir, &text, &permit, generate_human_slug)?;
113	    let rel_path = ws.config.changesets_dir.join(&filename).to_string_lossy().into_owned();
114	
115	    match global.format {
116	        OutputFormat::Json => {
117	            let report = AddReport {
118	                schema_version: SCHEMA_VERSION,
119	                path: rel_path,
120	                content: None,
121	                diagnostics: vec![],
122	            };
123	            emit_report(&mut std::io::stdout(), &report, false)?;
124	        }
125	        OutputFormat::Text => {
126	            log_line(global.format, &format!("Added changeset: {rel_path}"))?;
127	        }
128	    }
129	    if wizard {
130	        prompt_line("Next: commit it with your change; `callisto release --dry-run` previews the release.");
131	    }
132	
133	    Ok(ExitCode::SUCCESS)
134	}
