136	/// A changeset summary: trimmed and never blank, whichever way it was supplied.
137	#[derive(Clone, Debug, PartialEq, Eq)]
138	struct Summary(String);
139	
140	impl Summary {
141	    fn new(text: &str) -> Result<Self, CliError> {
142	        let trimmed = text.trim();
143	        if trimmed.is_empty() {
144	            return Err(CliError::AddSummaryEmpty);
145	        }
146	        Ok(Self(trimmed.to_owned()))
147	    }
