150	/// The wizard's questions; a scripted implementation drives tests. Esc or Ctrl-C at any of them is
151	/// [`CliError::Cancelled`].
152	trait AddPrompter {
153	    /// The indices the contributor ticked; `checked` says which start ticked.
154	    fn multi_select(&mut self, prompt: &str, items: &[String], checked: &[bool]) -> Result<Vec<usize>, CliError>;
155	    /// The summary; an empty answer opens `$EDITOR` for a longer one. `None` when the editor saves nothing.
156	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError>;
157	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
158	}
159	
160	/// Rows a package list shows before it pages.
161	const PAGE: usize = 15;
162	
163	struct TerminalAddPrompter {
164	    _allowed: tty::Prompts,
165	}
166	
167	impl AddPrompter for TerminalAddPrompter {
168	    fn multi_select(&mut self, prompt: &str, items: &[String], checked: &[bool]) -> Result<Vec<usize>, CliError> {
169	        let ticked: Vec<usize> = checked
170	            .iter()
171	            .enumerate()
172	            .filter(|(_, on)| **on)
173	            .map(|(index, _)| index)
174	            .collect();
175	        let picked = MultiSelect::new(prompt, items.to_vec())
176	            .with_default(&ticked)
177	            .with_page_size(PAGE)
178	            .raw_prompt()?;
179	        Ok(picked.into_iter().map(|option| option.index).collect())
180	    }
181	
182	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError> {
183	        let mut editor = tty::Editor::from_env();
184	        loop {
185	            let hint = match &editor {
186	                Some(editor) => format!("{prompt} (leave empty to open ${}; Esc cancels)", editor.variable()),
187	                None => format!("{prompt} (Esc cancels)"),
188	            };
189	            let opens_editor = editor.is_some();
190	            let line = Text::new(&hint)
191	                .with_validator(move |line: &str| {
192	                    Ok(match Summary::new(line) {
193	                        Err(error) if !(opens_editor && line.is_empty()) => {
194	                            Validation::Invalid(error.to_string().into())
195	                        }
196	                        _ => Validation::Valid,
197	                    })
198	                })
199	                .prompt()?;
200	            if let Ok(summary) = Summary::new(&line) {
201	                return Ok(Some(summary));
202	            }
203	            // The validator lets an empty line through only when there is an editor to open.
204	            let Some(chosen) = editor.take() else { continue };
205	            match chosen.edit() {
206	                Ok(saved) => return Ok(saved.and_then(|text| Summary::new(&text).ok())),
207	                // The answers so far are kept: the summary is asked for inline instead.
208	                Err(unusable) => prompt_line(&format!("warning: {unusable}")),
209	            }
210	        }
211	    }
212	
213	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
214	        Ok(Confirm::new(prompt).with_default(default).prompt()?)
215	    }
216	}
