218	/// A package the wizard offers, and whether it changed since its last tag.
219	struct Choice {
220	    name: String,
221	    changed: bool,
222	}
223	
224	/// The interactive wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor (the
225	/// remainder default to patch), a summary unless one was given, then a review to confirm. Changed packages are listed
226	/// first and start ticked. `None` when the contributor declines the review or the editor saves nothing, having been
227	/// told nothing was written.
228	fn run_wizard(
229	    choices: &[Choice],
230	    summary: Option<Summary>,
231	    prompter: &mut impl AddPrompter,
232	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
233	    let answers = ask(choices, summary, prompter)?;
234	    if answers.is_none() {
235	        prompt_line(tty::CANCELLED);
236	    }
237	    Ok(answers)
238	}
239	
240	fn ask(
241	    choices: &[Choice],
242	    summary: Option<Summary>,
243	    prompter: &mut impl AddPrompter,
244	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
245	    if choices.is_empty() {
246	        return Err(CliError::AddNoPackagesInWorkspace);
247	    }
248	
249	    let mut ordered: Vec<&Choice> = choices.iter().collect();
250	    ordered.sort_by_key(|choice| !choice.changed);
251	    let labels: Vec<String> = ordered
252	        .iter()
253	        .map(|choice| {
254	            if choice.changed {
255	                format!("{} (changed)", choice.name)
256	            } else {
257	                choice.name.clone()
258	            }
259	        })
260	        .collect();
261	    let checked: Vec<bool> = ordered.iter().map(|choice| choice.changed).collect();
262	    let selected_indices = prompter.multi_select(
263	        "Packages in this change (Space toggles, Enter confirms, Esc cancels)",
264	        &labels,
265	        &checked,
266	    )?;
267	    if selected_indices.is_empty() {
268	        return Err(CliError::AddNoPackagesSelected);
269	    }
270	    let selected_packages: Vec<String> = selected_indices.into_iter().map(|i| ordered[i].name.clone()).collect();
271	    let unticked = vec![false; selected_packages.len()];
272	
273	    let majors = prompter.multi_select(
274	        "Which are a MAJOR bump? (breaking changes only)",
275	        &selected_packages,
276	        &unticked,
277	    )?;
278	    let major_set: std::collections::HashSet<usize> = majors.into_iter().collect();
279	
280	    let minor_candidates: Vec<String> = selected_packages
281	        .iter()
282	        .enumerate()
283	        .filter(|(idx, _)| !major_set.contains(idx))
284	        .map(|(_, name)| name.clone())
285	        .collect();
286	    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
287	        std::collections::HashSet::new()
288	    } else {
289	        let minors = prompter.multi_select(
290	            "Which are a MINOR bump? (the rest get PATCH)",
291	            &minor_candidates,
292	            &unticked[..minor_candidates.len()],
293	        )?;
294	        minors.into_iter().map(|idx| minor_candidates[idx].clone()).collect()
295	    };
296	
297	    let entries: Vec<Entry> = selected_packages
298	        .iter()
299	        .enumerate()
300	        .map(|(idx, name)| Entry {
301	            name: name.clone(),
302	            severity: if major_set.contains(&idx) {
303	                Severity::Major
304	            } else if minor_set.contains(name) {
305	                Severity::Minor
306	            } else {
307	                Severity::Patch
308	            },
309	        })
310	        .collect();
311	
312	    let summary = match summary {
313	        Some(summary) => summary,
314	        None => match prompter.summary("Changelog summary")? {
315	            Some(summary) => summary,
316	            None => return Ok(None),
317	        },
318	    };
319	
320	    prompt_line(&review(&entries, &summary.0));
321	    Ok(prompter
322	        .confirm("Write this changeset?", true)?
323	        .then_some((entries, summary)))
324	}
325	
326	/// What the changeset will record: each package's bump, then the summary as it reaches the changelog.
327	fn review(entries: &[Entry], summary: &str) -> String {
328	    let mut text = String::from("\nThis changeset records:\n");
329	    for entry in entries {
330	        text.push_str(&format!("  {:<5}  {}\n", entry.severity.to_string(), entry.name));
331	    }
332	    text.push('\n');
333	    for line in summary.trim().lines() {
334	        text.push_str(&format!("  {line}\n"));
335	    }
336	    text
337	}
