339	/// Parses a CLI-supplied severity string, reporting every value `Severity`
340	/// actually accepts (`none`, `patch`, `minor`, `major`) on failure -- not a
341	/// stale subset that omits `none`.
342	fn parse_severity(sev_str: &str) -> Result<Severity, CliError> {
343	    sev_str.parse().map_err(|_err| CliError::InvalidSeverity {
344	        value: sev_str.to_string(),
345	    })
346	}
