348	/// The wizard's packages, named by `.display_name()` so `cargo/foo` and `npm/foo` stay distinct in a polyglot workspace.
349	/// When the changed packages cannot be worked out, says so once and offers every package unticked.
350	fn wizard_choices<'a>(
351	    packages: impl Iterator<Item = &'a callisto_model::Package>,
352	    changed: Result<std::collections::BTreeMap<callisto_model::PackageId, bool>, callisto_graph::GraphError>,
353	) -> Vec<Choice> {
354	    let changed = changed.unwrap_or_else(|error| {
355	        prompt_line(&format!(
356	            "warning: could not tell which packages changed since their last release, so none is ticked: {error}"
357	        ));
358	        std::collections::BTreeMap::new()
359	    });
360	    packages
361	        .map(|pkg| Choice {
362	            name: pkg.id.display_name(),
363	            changed: changed.get(&pkg.id).copied().unwrap_or(false),
364	        })
365	        .collect()
366	}
