28	        std::fs::create_dir_all(root.join(format!("packages/{name}"))).unwrap();
29	        std::fs::write(
30	            root.join(format!("packages/{name}/package.json")),
31	            format!(r#"{{"name":"{name}","version":"1.0.0"}}"#),
32	        )
