46	/// `callisto add` on a pty: the child, the master side to type into, and everything it has printed so far.
47	struct Session {
48	    child: Child,
49	    master: std::fs::File,
50	    /// The child's terminal, kept open to read its settings after the child exits.
51	    tty: std::fs::File,
52	    screen: Arc<Mutex<String>>,
53	}
54	
55	impl Session {
56	    fn start(root: &Path) -> Self {
57	        Self::start_with(root, &["add"], &[])
58	    }
59	
60	    /// `callisto <args>` with `env` set; `VISUAL` and `EDITOR` are unset unless `env` names them.
61	    fn start_with(root: &Path, args: &[&str], env: &[(&str, &str)]) -> Self {
62	        Self::launch(root, args, env, true)
63	    }
64	
65	    /// `callisto <args>` with stdin and stdout on the terminal and stderr piped; read it with [`Session::stderr`].
66	    fn start_with_piped_stderr(root: &Path, args: &[&str]) -> Self {
67	        Self::launch(root, args, &[], false)
68	    }
69	
70	    fn stderr(&mut self) -> String {
71	        let mut text = String::new();
72	        self.child.stderr.take().unwrap().read_to_string(&mut text).unwrap();
73	        text
74	    }
75	
76	    fn launch(root: &Path, args: &[&str], env: &[(&str, &str)], stderr_on_terminal: bool) -> Self {
77	        let master = openpt(OpenptFlags::RDWR | OpenptFlags::NOCTTY).unwrap();
78	        grantpt(&master).unwrap();
79	        unlockpt(&master).unwrap();
80	        let name = ptsname(&master, Vec::new()).unwrap();
81	        let tty = std::fs::OpenOptions::new()
82	            .read(true)
83	            .write(true)
84	            .open(name.to_str().unwrap())
85	            .unwrap();
86	        rustix::termios::tcsetwinsize(
87	            &tty,
88	            rustix::termios::Winsize {
89	                ws_row: 30,
90	                ws_col: 120,
91	                ws_xpixel: 0,
92	                ws_ypixel: 0,
93	            },
94	        )
95	        .unwrap();
96	        let child = Command::new(env!("CARGO_BIN_EXE_callisto"))
97	            .args(["--cwd", root.to_str().unwrap()])
98	            .args(args)
99	            .env_remove("VISUAL")
100	            .env_remove("EDITOR")
101	            .envs(env.iter().copied())
102	            .env("TERM", "xterm-256color")
103	            .stdin(Stdio::from(tty.try_clone().unwrap()))
104	            .stdout(Stdio::from(tty.try_clone().unwrap()))
105	            .stderr(if stderr_on_terminal {
106	                Stdio::from(tty.try_clone().unwrap())
107	            } else {
108	                Stdio::piped()
109	            })
110	            .spawn()
111	            .unwrap();
112	        let master = std::fs::File::from(master);
113	        let screen = Arc::new(Mutex::new(String::new()));
114	        let mut reader = master.try_clone().unwrap();
115	        let sink = Arc::clone(&screen);
116	        std::thread::spawn(move || {
117	            let mut buf = [0u8; 4096];
118	            // The read fails with EIO once the child has exited and closed the terminal.
119	            while let Ok(n @ 1..) = reader.read(&mut buf) {
120	                sink.lock().unwrap().push_str(&String::from_utf8_lossy(&buf[..n]));
121	            }
122	        });
123	        Session {
124	            child,
125	            master,
126	            tty,
127	            screen,
128	        }
129	    }
130	
131	    fn screen(&self) -> String {
132	        self.screen.lock().unwrap().clone()
133	    }
134	
135	    /// Waits until the output contains `text` `times` times, then types `keys`.
136	    fn after(&mut self, text: &str, times: usize, keys: &str) {
137	        let deadline = Instant::now() + Duration::from_secs(20);
138	        while self.screen().matches(text).count() < times {
139	            assert!(Instant::now() < deadline, "never saw {text:?}:\n{}", self.screen());
140	            std::thread::sleep(Duration::from_millis(20));
141	        }
142	        // Let the prompt finish drawing and switch the terminal to raw mode before typing.
143	        std::thread::sleep(Duration::from_millis(200));
144	        self.master.write_all(keys.as_bytes()).unwrap();
145	    }
