147	    /// Delivers SIGINT to the child itself, as `kill -INT` or a closing terminal would, with no Ctrl-C byte typed.
148	    fn interrupt(&self) {
149	        let status = Command::new("kill")
150	            .args(["-INT", &self.child.id().to_string()])
151	            .status()
152	            .unwrap();
153	        assert!(status.success());
154	    }
