156	    /// The terminal is back in line mode with echo, as the shell expects after the child exits.
157	    fn assert_terminal_restored(&self) {
158	        let out = Command::new("stty")
159	            .arg("-a")
160	            .stdin(self.tty.try_clone().unwrap())
161	            .output()
162	            .unwrap();
