171	    fn exit_code(&mut self) -> Option<i32> {
172	        self.status().code()
173	    }
174	
175	    fn status(&mut self) -> ExitStatus {
176	        let deadline = Instant::now() + Duration::from_secs(20);
177	        loop {
178	            if let Some(status) = self.child.try_wait().unwrap() {
179	                std::thread::sleep(Duration::from_millis(200));
180	                return status;
181	            }
182	            assert!(Instant::now() < deadline, "add did not exit:\n{}", self.screen());
183	            std::thread::sleep(Duration::from_millis(20));
184	        }
185	    }
186	}
